import {expect,it} from 'vitest';
import {arcControlProposals,ARC_POLICY_SCHEMA} from '../scripts/v0/optimizer/arc_control_policy.ts';
import {arcControlsSimilar} from '../scripts/v0/optimizer/arc_motion_control.ts';

const tree={left:[1,-1,-1],right:[2,-1,-1],feature:[0,-2,-2],threshold:[0,0,0]};
const query=Array(57).fill(0);
const row=(index:number,distance:number,leaf:number)=>({features:Array(57).fill(distance),proximityLeaves:[leaf],target:Array(10).fill(index)});
const policy=(exemplars:ReturnType<typeof row>[])=>({featureSchema:ARC_POLICY_SCHEMA,featureCount:57,proximityTrees:[tree],exemplars});

it('preserves original row order when rounded scores tie across partitions',()=>{
  const model=policy(Array.from({length:100},(_,i)=>row(i,i%2?2**100:0,i%2?1:2)));
  // Every score rounds to one, although odd rows have the closer partition.
  expect(arcControlProposals(query,0,1,model,8).map(c=>c.entry)).toEqual(Array.from({length:8},(_,i)=>30*i));
});

it('matches exhaustive finite ranking before diverse proposal selection',()=>{
  let seed=0x7326c11;
  const random=()=>((seed=(Math.imul(seed,1664525)+1013904223)>>>0)/2**32);
  for(let trial=0;trial<60;trial++){
    const exemplars=Array.from({length:200},(_,i)=>row(i,Math.floor(random()*10),random()<.5?1:2));
    const count=[1,3,8,24][trial%4],limit=Math.max(24,count*8);
    const ranked=exemplars.map(r=>{
      const distance=r.features.reduce((sum,x,j)=>sum+x*x*(j<7?2:j<47?1:4),0);
      return {r,score:(r.proximityLeaves[0]===1?0:1)+distance/(1+distance)};
    }).sort((a,b)=>a.score-b.score).slice(0,limit);
    const expected:ReturnType<typeof arcControlProposals>=[];
    for(const {r} of ranked){
      const c=arcControlProposals(query,0,1,policy([r]),1)[0];
      if(expected.some(p=>arcControlsSimilar(c,p)))continue;
      expected.push(c);if(expected.length===count)break;
    }
    expect(arcControlProposals(query,0,1,policy(exemplars),count)).toEqual(expected);
  }
});

it('rebuilds partition eligibility and memberships when model arrays are replaced',()=>{
  const model=policy([row(0,1,2),row(1,2,1)]);
  expect(arcControlProposals(query,0,1,model,1)[0].entry).toBe(30);
  model.exemplars=[row(0,1,1),row(1,2,2)];
  expect(arcControlProposals(query,0,1,model,1)[0].entry).toBe(0);
  model.proximityTrees=[{...tree,threshold:[-1,0,0]}];
  expect(arcControlProposals(query,0,1,model,1)[0].entry).toBe(30);
  model.exemplars=[row(0,Infinity,1),row(1,2,2)];
  // NaN scores retain the historical stable-sort behavior.
  expect(arcControlProposals(query,0,1,model,1)[0].entry).toBe(0);
});
